    required_operation: "Edge Banding"
  }
};

const panelCode = $json.panel_code;
const panel = panels[panelCode];

if (!panel) {
  return [{
    json: {
      found: false,
      panel_code: panelCode,
      source: "Panel Database"
    }
  }];
}

return [{
  json: {
    found: true,
    panel,
    source: `Panel ${panelCode}`
  }
}];
